-- D-25 ISSUE: FSQM-028 Site and Local Environment Risk Assessment. Approved GJM, effective 2026-10-07.
-- First issue: revision "New". Closes the document side of the Non-Compliant finding against SQF 11.1.1.1.
--
-- Changed from the draft of 2026-09-28 (20260928000007):
--   - the pest prevention program was issued on 2026-09-29 and is now named as a control (FSQM-031, FRM-914);
--   - the "two controls not yet in force" note becomes one: the water supply program (FSQM-033) is in draft;
--   - "copies are attached" now says what is true: the State food permit is attached, the others follow.
-- The attachment (the State food permit) is kept as it is. One UPDATE, guarded on the md5 of the content
-- read from production on 2026-10-07 (attachments included).
--
-- After issue, for the site: attach the local business licence, the certificate of occupancy and the FDA
-- facility registration; confirm the State permit covers unit 425; renew the FDA registration by 2026-12-31.

begin;

do $guard$
declare h text;
begin
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-028' and status = 'draft';
  if h is distinct from '1a6b2d5f8f786e16c200162c41b04032' then raise exception 'FSQM-028 is not the draft that was read (md5 %).', h; end if;
  if not exists (select 1 from public.sop_documents where sop_number = 'FSQM-031' and status = 'active') then
    raise exception 'FSQM-031 is not issued; FSQM-028 names it as a control in force.';
  end if;
end $guard$;

update public.sop_documents
   set content = jsonb_build_object('attachments', content->'attachments') || $j28${"scope": "Units 415 and 425 Specialty Pt - the buildings, their grounds and approach - and the activities in the surrounding area. Hazards inside the process are assessed in FSQM-016, not here.", "purpose": "This assessment records what surrounds the site, what in the local area or on the grounds could affect the safety of the product made here, what controls the site relies on for each, and when the assessment is looked at again. It also holds the approvals under which the premises operate.", "records": "The assessment itself is the record, together with the operating approvals attached to it. The monthly grounds and proofing checks are recorded on FRM-913.", "procedure": ["The site and what is around it", "• The site occupies two units, 415 and 425, in a light industrial complex. The neighbouring units are warehousing and light industry. There is no other food business in the complex, and no residential use.", "• The approach and yard are paved and drain well. There is no standing water after rain, no unsealed ground raising dust against the building, and no landscaping planted against the walls.", "• Waste leaves to a lidded dumpster in the complex, provided and emptied by the building (FSQM-037).", "• Deliveries and collections are made at the unit doors. Doors are kept closed except while goods are moving (FSQM-012).", "What was assessed, and what was found", "• NEIGHBOURING ACTIVITIES - warehousing and light industry. No process next door emits dust, smoke, odour or effluent that reaches the site, and no neighbour handles a material that would matter if it did. Risk: low. Control: doors kept closed; anything noticed from a neighbour is raised under this assessment.", "• A NEW OR CHANGED NEIGHBOUR is the risk this bullet really carries. A unit in a complex can change tenant without notice, and a tenant that raises dust or odour, or stores chemicals, changes the answer above. Control: the review trigger in the last Part.", "• TRAFFIC AND DUST - the complex carries ordinary commercial traffic on paved surfaces. Risk: low. Control: paved yard, doors closed, and the grounds checked monthly on FRM-913 (row 11.1.8).", "• PESTS FROM OUTSIDE - a shared complex with a shared waste area is where pest pressure comes from, not from inside. Risk: moderate, and the ordinary one for this site. Controls: the dumpster lid kept closed and waste out daily (FSQM-037); doors closed and the building's proofing checked monthly on FRM-913 (rows 11.1.5 and 11.1.8); a contracted pest control service under the pest prevention program (FSQM-031).", "• DRAINAGE AND STANDING WATER - none observed on the paved yard. Standing water beside a food building breeds insects and can be tracked in. Risk: low while the paving drains. Control: the monthly grounds check; any pooling that appears is a finding.", "• SEVERE WEATHER - the site is in Florida, where a storm can bring flooding, a power loss long enough to matter to the walk-ins, or damage to the roof and doors. Risk: low in frequency, high in consequence. Controls: refrigeration is alarmed and monitored (SOP-401); after any storm that causes flooding, a power outage or visible damage, the building is inspected before production restarts, and product held under FSQM-018 if its condition is in doubt.", "• EXTERNAL CONTAMINATION SOURCES - there is no waste transfer station, landfill, farm, livestock, canal, pond or heavy industry in the area, and nothing overhead that discharges over the site. Risk: none identified.", "• UTILITIES AND SERVICES - water is supplied by the municipal system; there is no well and no on-site treatment. Risk: low, and assessed with the water program (FSQM-033).", "• SECURITY OF THE SITE FROM OUTSIDE - deliberate contamination is assessed separately under the food defence program, not here.", "Controls this assessment relies on", "• FSQM-012 Good Manufacturing Practices - doors, grounds, proofing and the monthly inspection on FRM-913, whose rows 11.1.5 and 11.1.8 cover proofing and the grounds.", "• FSQM-037 Waste Management - the dumpster, its lid and daily removal.", "• FSQM-031 Pest Prevention Program - the contracted pest control service and the pest activity log (FRM-914).", "• SOP-401 Temperature-Controlled Storage - the alarmed walk-ins that make a power loss visible.", "• FSQM-018 Non-Conforming Product and Equipment - product whose condition is in doubt after an event.", "> ONE CONTROL THIS ASSESSMENT LEANS ON IS NOT YET IN FORCE. The water supply program (FSQM-033) is in draft. The municipal supply is assessed there, and this assessment is revisited when that program is issued.", "Approval to operate", "• The premises are approved to operate by the relevant authorities and the site holds: a State food establishment or manufacturer licence; a local business licence and certificate of occupancy; and a current FDA food facility registration (SQF 11.1.1.1).", "• The State food permit is attached to this document. Senior Site Management holds the others and attaches a copy of each here. Each is renewed before it expires, and the renewed copy replaces the old one.", "> THE FDA REGISTRATION RENEWS IN EVEN-NUMBERED YEARS, between 1 October and 31 December. 2026 is one. A lapsed registration is not a paperwork matter: it is a federal requirement for a facility that manufactures food, and an auditor asks to see it.", "Review", "• This assessment is reviewed at least once a year, and its review is evidenced by its revision (SQF 11.1.1.1).", "• It is reviewed before that whenever the area or the site changes: a new or changed neighbouring tenant, construction or demolition nearby, a change to the yard, drainage or waste arrangements, a storm or flood affecting the site, or a pest problem traced to something outside.", "• Anyone who notices such a change tells the SQF Practitioner, who decides whether the assessment is re-run."], "definitions": "Local activity: anything carried on outside the site's boundary whose effect can reach the site - a neighbouring operation, traffic, waste handling, construction, or weather.\nControl: something the site already does, named here with the document that governs it.", "responsibility": "Senior Site Management - owns this assessment, holds the operating approvals, and decides what to do when something in the area changes.\nSQF Practitioner - checks the grounds monthly on the GMP inspection and raises anything new for assessment.", "form_references": "FRM-913 - GMP / Food Safety Inspection Record (rows 11.1.5 pest proofing and 11.1.8 grounds)\nFRM-702 - Non-Conforming Material Hold & Tagging Record (product in doubt after an event)\nFRM-914 - Pest Activity Log", "revision_history": "New - 2026-10-07 - ISSUED under D-25. Approved GJM, effective 2026-10-07. Drafted 2026-09-28 for the single Non-Compliant finding against 11.1.1.1: the site had not assessed local activities or its environment.\n\nWHAT THE OWNER DESCRIBED (2026-09-28): two units in a light industrial complex whose neighbours are warehousing and light industry; a paved yard that drains with no standing water; nothing notable in the wider area - no landfill, waste transfer, farm, water body or heavy industry; and all three approvals held - State licence, local business licence and certificate of occupancy, and FDA facility registration.\n\nSO THE ASSESSMENT IS SHORT, AND SAYS SO. A low-risk site honestly assessed produces a short document. What matters in it is not the list of risks that came back low, but the two that did not: pest pressure from a shared complex with a shared waste area, and severe weather, which in Florida is infrequent and consequential rather than unlikely. Both are named with the control they rely on.\n\nCHANGED BETWEEN DRAFT AND ISSUE: the pest prevention program was issued on 2026-09-29 (FSQM-031) and is now named as a control. The water supply program (FSQM-033) is still in draft, and the assessment says so; it is revisited when that program is issued.\n\nTHE APPROVALS AT ISSUE: the State food permit is attached. Still to attach: the local business licence, the certificate of occupancy and the FDA food facility registration. The State permit names unit 415; whether it covers unit 425 is to be confirmed with the issuing authority.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.1.1.1 (premises location and approval: assess local activities and the site environment, control identified risks, review on change, and operate premises approved by the relevant authority).\n\nFSQM-012 Good Manufacturing Practices Program - the controls this assessment relies on.\nFSQM-037 Waste Management Program - the waste area.\nFSQM-031 Pest Prevention Program - pest pressure from the complex.\nSOP-401 Temperature-Controlled Storage - refrigeration alarms.\nFSQM-016 Food Safety Plan - hazards inside the process, which are not assessed here."}$j28$::jsonb,
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-07'
 where sop_number = 'FSQM-028' and status = 'draft';

do $verify$
declare c jsonb;
begin
  select content into c from public.sop_documents
   where sop_number = 'FSQM-028' and status = 'active' and revision = 'New' and approved_by = 'GJM'
     and effective_date = date '2026-10-07';
  if c is null then raise exception 'FSQM-028 was not issued.'; end if;
  if jsonb_array_length(c->'procedure') <> 30 then raise exception 'FSQM-028 has % lines.', jsonb_array_length(c->'procedure'); end if;
  if jsonb_array_length(c->'attachments') <> 1 then raise exception 'the attached permit was not kept.'; end if;
  if c::text ~ 'TWO CONTROLS' then raise exception 'the old note is still there.'; end if;
  if c::text ~* '(Diana|Gabriela|Richard|Mercer|Botta)' then raise exception 'a controlled document names a person.'; end if;
  if exists (select 1 from public.sop_documents where sop_number = 'FSQM-028' and status = 'draft') then
    raise exception 'a draft is left behind.';
  end if;
end $verify$;

commit;
